#include <bits/stdc++.h>
#define MAX_INF 17446744073709551616ULL
#define ULLONG unsigned long long
using namespace std;

ULL modulus, size_n, power_k, dp_table[18][250005];
ULL fact[250005], inv_fact[250005];

ULL fastExponentiation(ULL base, ULL exp) {
    ULL res = 1ULL, cur = base;
    while (exp > 0) {
        if (exp & 1ULL) res = (res * cur) % modulus;
        cur = (cur * cur) % modulus;
        exp >>= 1ULL;
    }
    return res;
}

ULL nCr(int a, int b) {
    return (((fact[a] * inv_fact[b]) % modulus) * inv_fact[a - b]) % modulus;
}

ULL solve() {
    int i, j, mask;
    fact[0] = 1ULL;
    for (i = 1; i <= size_n; i++) {
        fact[i] = (fact[i - 1] * (ULL)i) % modulus;
    }
    inv_fact[size_n] = fastExponentiation(fact[size_n], modulus - 2ULL);
    for (i = size_n - 1; i >= 0; i--) {
        inv_fact[i] = (inv_fact[i + 1] * (ULL)(i + 1)) % modulus;
    }
    for (i = 1; i <= size_n; i++) {
        dp_table[1][i] = inv_fact[i];
    }
    ULL total = dp_table[1][size_n] * nCr((int)power_k, 1) % modulus;
    int limit = min(17, (int)power_k);
    for (i = 2; i <= limit; i++) {
        for (j = size_n; j > 0; j = (j - 1) & size_n) {
            if (dp_table[i - 1][j] == 0) continue;
            int remaining_mask = size_n ^ j;
            for (mask = remaining_mask; mask > 0; mask = (mask - 1) & remaining_mask) {
                dp_table[i][j + mask] += dp_table[i - 1][j] * inv_fact[mask];
                if (dp_table[i][j + mask] > MAX_INF) dp_table[i][j + mask] %= modulus;
            }
        }
        for (j = size_n; j > 0; j = (j - 1) & size_n) {
            dp_table[i][j] %= modulus;
        }
        total += dp_table[i][size_n] * nCr((int)power_k, i);
        total %= modulus;
    }
    total *= fact[size_n];
    total %= modulus;
    return total;
}

int main() {
    cin >> size_n >> power_k >> modulus;
    ULL res = fastExponentiation(power_k, size_n);
    if (size_n % 2 == 0) {
        res = (res - solve() + modulus) % modulus;
    }
    cout << res << endl;
    return 0;
}
